import{_ as a,o as i,c as r,a2 as l}from"./chunks/framework.CTZjucLO.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"regulament-civili.md","filePath":"regulament-civili.md"}'),t={name:"regulament-civili.md"};function u(o,e,n,c,s,p){return i(),r("div",null,[...e[0]||(e[0]=[l('<h2 id="📜-regulament-civili-romana" tabindex="-1">📜 Regulament Civili (Română) <a class="header-anchor" href="#📜-regulament-civili-romana" aria-label="Permalink to &quot;📜 Regulament Civili (Română)&quot;">​</a></h2><hr><h2 id="cap-1-dispozitii-generale" tabindex="-1">CAP. 1 - DISPOZIȚII GENERALE <a class="header-anchor" href="#cap-1-dispozitii-generale" aria-label="Permalink to &quot;CAP. 1 - DISPOZIȚII GENERALE&quot;">​</a></h2><h3 id="_1-1-statutul-civililor" tabindex="-1">1.1 Statutul civililor <a class="header-anchor" href="#_1-1-statutul-civililor" aria-label="Permalink to &quot;1.1 Statutul civililor&quot;">​</a></h3><p>Jucătorii care aleg statutul de civil trebuie să respecte regulamentul general al serverului, precum și prezentul regulament.</p><h3 id="reguli" tabindex="-1">Reguli <a class="header-anchor" href="#reguli" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Civilii pot participa la activități ilegale, precum jefuirea magazinelor sau a bancomatelor, doar cu respectarea integrală a <strong>Regulamentului Jafurilor</strong>.</li><li>Toți jucătorii au obligația de a citi și respecta atât prezentul regulament, cât și regulamentul general al comunității <strong>LEGACY OF CLT</strong>.</li><li>Fiecare civil trebuie să se adapteze stilului de joc promovat de server și să respecte mecanicile Roleplay.</li></ul><hr><h2 id="cap-2-comportament" tabindex="-1">CAP. 2 - COMPORTAMENT <a class="header-anchor" href="#cap-2-comportament" aria-label="Permalink to &quot;CAP. 2 - COMPORTAMENT&quot;">​</a></h2><h3 id="_2-1-comunicarea-pe-server" tabindex="-1">2.1 Comunicarea pe server <a class="header-anchor" href="#_2-1-comunicarea-pe-server" aria-label="Permalink to &quot;2.1 Comunicarea pe server&quot;">​</a></h3><p>Comunicarea trebuie să fie civilizată și să nu afecteze experiența celorlalți jucători.</p><h3 id="reguli-1" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-1" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Este interzisă utilizarea culorilor pe chatul global.</li><li>Este interzisă afișarea unui nume colorat.</li><li>Este interzis spam-ul sau transmiterea repetată a mesajelor pe chat.</li></ul><hr><h3 id="_2-2-respect-si-fair-play" tabindex="-1">2.2 Respect și Fair Play <a class="header-anchor" href="#_2-2-respect-si-fair-play" aria-label="Permalink to &quot;2.2 Respect și Fair Play&quot;">​</a></h3><p>Respectul reciproc reprezintă unul dintre principiile fundamentale ale comunității.</p><h3 id="reguli-2" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-2" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Toți jucătorii trebuie să manifeste respect față de ceilalți participanți.</li><li>Comportamentul toxic sau acțiunile care afectează experiența altor jucători pot fi sancționate de echipa Staff.</li><li>Fair-play-ul trebuie respectat în orice situație Roleplay.</li></ul><hr><h2 id="cap-3-armament" tabindex="-1">CAP. 3 - ARMAMENT <a class="header-anchor" href="#cap-3-armament" aria-label="Permalink to &quot;CAP. 3 - ARMAMENT&quot;">​</a></h2><h3 id="_3-1-detinerea-armelor" tabindex="-1">3.1 Deținerea armelor <a class="header-anchor" href="#_3-1-detinerea-armelor" aria-label="Permalink to &quot;3.1 Deținerea armelor&quot;">​</a></h3><p>Achiziționarea și deținerea armelor trebuie să respecte regulile serverului.</p><h3 id="reguli-3" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-3" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Este interzisă achiziționarea sau deținerea armelor de foc ori a armelor albe înainte de acumularea a <strong>50 de ore de joc</strong>.</li><li>Deținerea armelor fără respectarea regulamentului poate atrage sancțiuni Roleplay și administrative.</li></ul><hr><h3 id="_3-2-permisul-de-port-arma" tabindex="-1">3.2 Permisul de port-armă <a class="header-anchor" href="#_3-2-permisul-de-port-arma" aria-label="Permalink to &quot;3.2 Permisul de port-armă&quot;">​</a></h3><p>Jucătorii care dețin permis de port-armă trebuie să respecte condițiile impuse de legislația Roleplay.</p><h3 id="reguli-4" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-4" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Este permisă deținerea unui singur pistol.</li><li>Limitele impuse de permis trebuie respectate în permanență.</li><li>Nerespectarea condițiilor poate conduce la: <ul><li>confiscarea permisului;</li><li>confiscarea armamentului;</li><li>aplicarea unei amenzi;</li><li>sancționarea pentru posesie ilegală de arme.</li></ul></li><li>Permisul de port-armă nu garantează recuperarea armelor după respawn.</li></ul><hr><h2 id="cap-4-roleplay" tabindex="-1">CAP. 4 - ROLEPLAY <a class="header-anchor" href="#cap-4-roleplay" aria-label="Permalink to &quot;CAP. 4 - ROLEPLAY&quot;">​</a></h2><h3 id="_4-1-calitatea-roleplay-ului" tabindex="-1">4.1 Calitatea Roleplay-ului <a class="header-anchor" href="#_4-1-calitatea-roleplay-ului" aria-label="Permalink to &quot;4.1 Calitatea Roleplay-ului&quot;">​</a></h3><p>Serverul încurajează dezvoltarea unor scenarii Roleplay complexe și realiste.</p><h3 id="reguli-5" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-5" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Conflictele dintre personaje trebuie să aibă întotdeauna o justificare Roleplay.</li><li>Acțiunile trebuie desfășurate exclusiv în contextul personajului (<strong>IC</strong>).</li><li>Certurile, insultele și provocările realizate în afara Roleplay-ului (<strong>OOC</strong>) sunt interzise.</li><li>Încălcarea acestor reguli poate conduce la <strong>Admin Jail</strong> sau suspendarea accesului pe server.</li></ul><hr><h2 id="cap-5-jafuri" tabindex="-1">CAP. 5 - JAFURI <a class="header-anchor" href="#cap-5-jafuri" aria-label="Permalink to &quot;CAP. 5 - JAFURI&quot;">​</a></h2><h3 id="_5-1-interactiuni-infractionale" tabindex="-1">5.1 Interacțiuni infracționale <a class="header-anchor" href="#_5-1-interactiuni-infractionale" aria-label="Permalink to &quot;5.1 Interacțiuni infracționale&quot;">​</a></h3><p>În timpul jafurilor trebuie respectate regulile privind bunurile care pot fi sustrase.</p><h3 id="reguli-6" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-6" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Este interzisă sustragerea documentelor personale ale altor jucători.</li><li>Nu pot fi furate: <ul><li>Cartea de identitate.</li><li>Permisul de conducere.</li><li>Permisul de port-armă.</li></ul></li></ul><hr><h2 id="cap-6-dispozitii-finale" tabindex="-1">CAP. 6 - DISPOZIȚII FINALE <a class="header-anchor" href="#cap-6-dispozitii-finale" aria-label="Permalink to &quot;CAP. 6 - DISPOZIȚII FINALE&quot;">​</a></h2><h3 id="_6-1-aplicarea-regulamentului" tabindex="-1">6.1 Aplicarea regulamentului <a class="header-anchor" href="#_6-1-aplicarea-regulamentului" aria-label="Permalink to &quot;6.1 Aplicarea regulamentului&quot;">​</a></h3><p>Toți civilii au obligația de a respecta prezentul regulament și regulamentul general al comunității.</p><h3 id="reguli-7" tabindex="-1">Reguli <a class="header-anchor" href="#reguli-7" aria-label="Permalink to &quot;Reguli&quot;">​</a></h3><ul><li>Necunoașterea regulamentului nu constituie o scuză.</li><li>Echipa administrativă își rezervă dreptul de a sancționa orice comportament care afectează experiența Roleplay.</li><li>Regulamentul poate fi modificat de administrație ori de câte ori este necesar.</li></ul><hr><h2 id="📌-nota" tabindex="-1">📌 NOTĂ <a class="header-anchor" href="#📌-nota" aria-label="Permalink to &quot;📌 NOTĂ&quot;">​</a></h2><p>Respectarea prezentului regulament este obligatorie pentru toți jucătorii care aleg statutul de <strong>civil</strong> pe serverul <strong>LEGACY OF CLT</strong>.</p><p>Scopul acestui regulament este menținerea unui mediu Roleplay realist, echilibrat și plăcut pentru întreaga comunitate.</p>',51)])])}const h=a(t,[["render",u]]);export{m as __pageData,h as default};
